"""Self-contained local browser replay of pose results; source images remain in place."""
import json


def make_page(data):
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False).replace('<','\\u003c')
    notice = ('<p><strong>急な角度変化の両端を要確認として保留しています。元の角度は詳細とイベントCSVに残しています。</strong> <a href="yaw_events.csv">角度の急変イベントCSV</a></p>' if data.get('yaw_quality') else '')
    return r'''<!doctype html><html lang="ja"><meta charset="utf-8"><title>上半身姿勢の確認</title>
<style>body{font:15px system-ui;margin:20px;color:#193143}canvas{max-width:100%;border:1px solid #a9b9c5;background:white}input[type=range]{width:min(850px,80%)}button,select{margin:4px}pre{white-space:pre-wrap;max-height:18em;overflow:auto}.panels{display:flex;flex-wrap:wrap;gap:12px}.panels canvas{object-fit:contain;max-height:600px}label{margin-right:12px}</style>
<h1>上半身姿勢・位置の同期確認</h1>__NOTICE__<p>肩・腰・耳の左右軸から向きを推定した暫定値です。耳の向きは頭部姿勢の近似で、遮蔽や左右誤認に弱く、実測精度は未検証です。位置は可視表面候補で、ID・校正も暫定です。灰色はID不明です。</p>
<label>時刻 <input type="range" id="slider" min="0" value="0" step="1"><span id="clock"></span></label><br><button id="play">再生</button><button id="stop">停止</button><label>再生速度<select id="rate"><option>0.5</option><option selected>1</option><option>2</option></select></label><label>グラフID<select id="track"></select></label><label>矢印<select id="angle"><option value="torso">上半身</option><option value="shoulder">肩</option><option value="hip">腰</option><option value="head">頭</option></select></label>
<div class="panels"><canvas id="image" width="960" height="540"></canvas><canvas id="map" width="700" height="400"></canvas></div>
<p>画像：元映像に関節を重畳。上面：横 X・縦 Y、矢印は選択部位の推定前方。10 m版の範囲外・保留・欠測は座標を表示しません。</p><canvas id="graph" width="1400" height="350"></canvas><p>上：yaw（度、X方向=0°、Y方向=90°）。下：隣接フレームの表面位置からの速度（m/s）。欠測と角度の±180°境界は線を切ります。縦線が選択時刻です。</p>
<label>確認対象 <select id="obs"></select></label><label>メモ <input id="note" size="45" placeholder="誤推定、遮蔽など"></label><button id="mark">現在の検出を記録</button><button id="download">確認メモCSVを保存</button><span id="marks"></span><pre id="details"></pre><p><a href="pose.csv">姿勢CSV</a> / <a href="gaps.csv">欠測区間CSV</a> / <a href="pose.json">姿勢データと設定</a></p>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),F=D.frames,s=document.getElementById('slider'),track=document.getElementById('track'),angle=document.getElementById('angle'),obs=document.getElementById('obs');s.max=F.length-1;
const ids=[...new Set(F.flatMap(f=>f.observations.map(o=>o.track_id)).filter(x=>x!==null))].sort((a,b)=>a-b); for(const id of ids){let o=document.createElement('option');o.value=id;o.textContent='ID '+id;track.appendChild(o)}
const img=document.getElementById('image'),ic=img.getContext('2d'),map=document.getElementById('map'),mc=map.getContext('2d'),graph=document.getElementById('graph'),gc=graph.getContext('2d'),color=id=>id===null?'#777':`hsl(${(Number(id)*137)%360},75%,42%)`;let timer=null,request=0,marks=[];
const points=F.flatMap(f=>f.observations.filter(o=>o.position_m).map(o=>o.position_m)),walls=Object.values(D.walls||{}).filter(Number.isFinite),xs=points.map(p=>p[0]).concat([0,10]),ys=points.map(p=>p[1]).concat([0,...walls]),xmin=Math.min(...xs)-.3,xmax=Math.max(...xs)+.3,ymin=Math.min(...ys)-.3,ymax=Math.max(...ys)+.3,scale=Math.min(620/(xmax-xmin||1),320/(ymax-ymin||1)),mx=x=>50+(x-xmin)*scale,my=y=>30+(ymax-y)*scale;
function drawMap(i){mc.clearRect(0,0,map.width,map.height);mc.font='14px sans-serif';mc.fillText('X →',625,390);mc.fillText('Y ↑',5,20);mc.strokeStyle='#e1e5e8';for(let x=Math.ceil(xmin);x<=xmax;x++){mc.beginPath();mc.moveTo(mx(x),my(ymin));mc.lineTo(mx(x),my(ymax));mc.stroke();mc.fillText(x,mx(x),my(ymin)+16)}for(const w of walls){mc.strokeStyle='#7e929a';mc.beginPath();mc.moveTo(mx(xmin),my(w));mc.lineTo(mx(xmax),my(w));mc.stroke()}
for(let j=0;j<=i;j++) for(const o of F[j].observations){let p=o.position_m;if(!p)continue;mc.fillStyle=color(o.track_id);if(j&&o.track_id!==null&&F[j].frame_index===F[j-1].frame_index+1&&F[j].elapsed_s-F[j-1].elapsed_s<=.15){let prev=F[j-1].observations.find(q=>q.track_id===o.track_id&&q.position_m);if(prev){mc.strokeStyle=color(o.track_id);mc.beginPath();mc.moveTo(mx(prev.position_m[0]),my(prev.position_m[1]));mc.lineTo(mx(p[0]),my(p[1]));mc.stroke()}}mc.beginPath();mc.arc(mx(p[0]),my(p[1]),j===i?5:1.5,0,7);mc.fill();if(j===i){mc.fillText(o.track_id===null?'ID ?':'ID '+o.track_id,mx(p[0])+6,my(p[1])-6);let a=o.angles[angle.value].yaw_deg;if(a!==null){let rad=a*Math.PI/180,x=mx(p[0]),y=my(p[1]),dx=Math.cos(rad)*30,dy=-Math.sin(rad)*30;mc.strokeStyle=color(o.track_id);mc.lineWidth=3;mc.beginPath();mc.moveTo(x,y);mc.lineTo(x+dx,y+dy);mc.lineTo(x+dx-8*Math.cos(rad-.5),y+dy+8*Math.sin(rad-.5));mc.moveTo(x+dx,y+dy);mc.lineTo(x+dx-8*Math.cos(rad+.5),y+dy+8*Math.sin(rad+.5));mc.stroke();mc.lineWidth=1}}}}
function drawGraph(i){gc.clearRect(0,0,graph.width,graph.height);gc.font='14px sans-serif';let t0=F[0].elapsed_s,t1=F[F.length-1].elapsed_s,tx=t=>55+(t-t0)/(t1-t0||1)*1300;gc.fillText('yaw °',4,20);gc.fillText('速度',4,198);gc.fillText('時刻 秒',1300,345);let chosen=track.value, rows=F.map(f=>f.observations.find(o=>String(o.track_id)===chosen&&o.track_id!==null));let maxv=Math.max(1,...rows.filter(Boolean).map(o=>o.speed_m_s||0));for(let part of ['shoulder','hip','torso','head']){gc.strokeStyle=({shoulder:'#e07c16',hip:'#579c40',torso:'#176fc1',head:'#aa46ac'})[part];gc.beginPath();let old=null;rows.forEach((o,j)=>{let y=o?.angles[part].yaw_deg;if(y===null||y===undefined){old=null;return}let x=tx(F[j].elapsed_s),py=95-y/180*75;if(old&&F[j].frame_index===F[j-1].frame_index+1&&F[j].elapsed_s-F[j-1].elapsed_s<=.15&&Math.abs(y-old.y)<180)gc.lineTo(x,py);else gc.moveTo(x,py);old={y}});gc.stroke();gc.fillText(part,65+['shoulder','hip','torso','head'].indexOf(part)*100,17)}gc.strokeStyle='#263e4d';gc.beginPath();let old=false;rows.forEach((o,j)=>{let v=o?.speed_m_s;if(v===null||v===undefined){old=false;return}let x=tx(F[j].elapsed_s),y=325-v/maxv*110;if(old&&F[j].frame_index===F[j-1].frame_index+1&&F[j].elapsed_s-F[j-1].elapsed_s<=.15)gc.lineTo(x,y);else gc.moveTo(x,y);old=true});gc.stroke();gc.fillText(maxv.toFixed(1)+' m/s',4,220);gc.strokeStyle='#d33';gc.beginPath();gc.moveTo(tx(F[i].elapsed_s),0);gc.lineTo(tx(F[i].elapsed_s),335);gc.stroke()}
function drawImage(i){let seq=++request,source=new Image();source.onload=()=>{if(seq!==request)return;img.width=source.width;img.height=source.height;ic.drawImage(source,0,0);ic.lineWidth=Math.max(2,source.width/600);ic.font=`${Math.max(14,source.width/70)}px sans-serif`;for(const o of F[i].observations){ic.strokeStyle=ic.fillStyle=color(o.track_id);if(o.bbox){let b=o.bbox;ic.strokeRect(b[0],b[1],b[2]-b[0],b[3]-b[1]);ic.fillText(o.track_id===null?'ID ?':'ID '+o.track_id,b[0],Math.max(15,b[1]-4))}for(const pair of [['left_shoulder','right_shoulder'],['left_hip','right_hip'],['left_shoulder','left_hip'],['right_shoulder','right_hip'],['left_ear','right_ear'],['left_eye','right_eye'],['nose','left_eye'],['nose','right_eye']]){let a=o.joints[pair[0]],b=o.joints[pair[1]];if(a.xy&&b.xy&&a.score>=D.metadata.keypoint_threshold&&b.score>=D.metadata.keypoint_threshold){ic.beginPath();ic.moveTo(...a.xy);ic.lineTo(...b.xy);ic.stroke()}}for(const q of Object.values(o.joints)){if(q.xy&&q.score>=D.metadata.keypoint_threshold){ic.beginPath();ic.arc(q.xy[0],q.xy[1],4,0,7);ic.fill()}}}};source.onerror=()=>{if(seq===request){ic.clearRect(0,0,img.width,img.height);ic.fillStyle='red';ic.fillText('元画像を読み込めません',20,40)}};source.src=F[i].image}
function render(){let i=Number(s.value),f=F[i];document.getElementById('clock').textContent=` ${f.elapsed_s.toFixed(3)} 秒 / frame ${f.frame_index}`;let old=obs.value;obs.replaceChildren();for(const o of f.observations){let n=document.createElement('option');n.value=o.observation_index;n.textContent=`検出 ${o.observation_index} / ID ${o.track_id??'不明'}`;obs.appendChild(n)}if([...obs.options].some(x=>x.value===old))obs.value=old;document.getElementById('details').textContent=JSON.stringify(f.observations,null,2);drawImage(i);drawMap(i);drawGraph(i)}function stop(){clearTimeout(timer);timer=null}function step(){let i=Number(s.value);if(i>=F.length-1){timer=null;return}timer=setTimeout(()=>{s.value=i+1;render();step()},Math.max(1,1000*(F[i+1].elapsed_s-F[i].elapsed_s)/Number(document.getElementById('rate').value)))}s.oninput=()=>{stop();render()};document.getElementById('play').onclick=()=>{if(!timer)step()};document.getElementById('stop').onclick=stop;track.onchange=angle.onchange=render;
document.getElementById('mark').onclick=()=>{if(!obs.value)return;let f=F[Number(s.value)],o=f.observations.find(q=>String(q.observation_index)===obs.value);marks.push([D.metadata.trial_id,f.frame_index,f.timestamp_ns,o.observation_index,o.track_id??'',document.getElementById('note').value]);document.getElementById('marks').textContent=` ${marks.length}件（保存するまでこのページ内）`};document.getElementById('download').onclick=()=>{let quote=x=>'"'+String(x).replaceAll('"','""')+'"',text='trial_id,frame_index,timestamp_ns,observation_index,track_id,note\r\n'+marks.map(r=>r.map(quote).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/csv;charset=utf-8'}));a.download='pose_review.csv';a.click();URL.revokeObjectURL(a.href)};render();
</script></html>'''.replace('__DATA__',payload).replace('__NOTICE__',notice)
